#import "../Sources/DDLCore.h"
#import "../Sources/SSLocalData.h"
static NSUInteger checks;
static void Check(BOOL ok,NSString *why){checks++;if(!ok){fprintf(stderr,"FAIL: %s\n",why.UTF8String);exit(1);}}
int main(){@autoreleasepool{
 NSDictionary *repository=@{@"fork":@"student/physics",@"upstream":@"teacher/physics"};NSArray *catalog=AMCourseCatalog(@[repository]);Check(catalog.count==1, @"repository has stable catalog identity");NSString *repoID=catalog[0][@"id"];Check([repoID isEqual:AMRepositoryCourseID(@"STUDENT/PHYSICS")],@"repository identity is case-insensitive");
 NSDictionary *local=AMNewCourse(@"  数学  ");Check([local[@"name"] isEqual:@"数学"] && !local[@"fork"],@"local course trims name without manufacturing repository");catalog=[catalog arrayByAddingObject:local];NSError *error=nil;Check(AMSaveCourseCatalog(catalog,&error),@"catalog saves");Check([AMStoredCourses(NULL) isEqual:catalog],@"catalog survives restart");Check([AMCourseForName(@" 数学\n",catalog)[@"id"] isEqual:local[@"id"]],@"exact unique trimmed name resolves");Check(!AMCourseForName(@"数学",[catalog arrayByAddingObject:AMNewCourse(@"数学")]),@"ambiguous names never choose");
 Check(!AMCourseForTask(@{@"subject":@"数学"},catalog),@"legacy category alone is not migrated");Check([AMCourseForTask(@{@"courseRepository":@"student/physics"},catalog)[@"id"] isEqual:repoID],@"legacy explicit repository recovers membership");Check(!AMCourseForTask(@{@"courseID":@"",@"sourceRepository":@"teacher/physics"},catalog),@"explicit unassociated membership does not borrow provenance");NSMutableDictionary *renamed=local.mutableCopy;renamed[@"name"]=@"数学进阶";Check([AMCourseForTask(@{@"courseID":local[@"id"]},@[renamed])[@"name"] isEqual:@"数学进阶"],@"rename resolves through stable identity");
 NSCalendar *calendar=[NSCalendar calendarWithIdentifier:NSCalendarIdentifierGregorian];calendar.timeZone=[NSTimeZone timeZoneWithName:@"Asia/Shanghai"];NSDate *now=DDLParseDate(@"2027-01-01 00:00",NSDate.date,calendar);NSString *sid=NSUUID.UUID.UUIDString;NSDictionary *template=@{@"id":@"template",@"title":@"旧名称",@"subject":@"其他",@"due":now,@"notes":@"旧备注",@"completed":@NO,@"reminderOffsets":@[@60,@0]};NSDictionary *rule=@{@"mode":@"fixed",@"unit":@"day",@"interval":@1,@"anchor":now,@"timeZone":@"Asia/Shanghai",@"holidayPolicy":@"keep",@"count":@10};NSArray *series=@[@{@"id":sid,@"template":template,@"rule":rule}];NSMutableArray *tasks=NSMutableArray.array;
 for(NSUInteger i=0;i<4;i++){NSMutableDictionary *task=template.mutableCopy;task[@"id"]=[NSString stringWithFormat:@"task-%lu",i];task[@"seriesID"]=sid;task[@"due"]=task[@"nominalDue"]=[now dateByAddingTimeInterval:i*86400];task[@"completed"]=@(i==0);if(i==2){task[@"notes"]=@"单次备注";task[@"occurrenceEdited"]=@YES;task[@"occurrenceOverrides"]=@[@"notes"];}if(i==3)task[@"deleted"]=@YES;[tasks addObject:task];}
 NSMutableDictionary *edited=[tasks[1] mutableCopy];edited[@"title"]=@"新名称";edited[@"notes"]=@"新备注";NSDictionary *batch=DDLSeriesEdit(tasks,series,tasks[1],edited,0,NO);Check([batch[@"tasks"][0][@"title"] isEqual:@"旧名称"] && [batch[@"tasks"][1][@"title"] isEqual:@"新名称"],@"only this occurrence changes");Check([batch[@"tasks"][1][@"occurrenceOverrides"] containsObject:@"title"],@"single field exception tracked");
 batch=DDLSeriesEdit(tasks,series,tasks[1],edited,1,NO);Check([batch[@"tasks"][0][@"title"] isEqual:@"旧名称"] && [batch[@"tasks"][2][@"title"] isEqual:@"新名称"] && [batch[@"tasks"][2][@"notes"] isEqual:@"单次备注"],@"future edits preserve field-specific exceptions while applying other changed fields");Check([batch[@"tasks"][3][@"deleted"] boolValue] && [batch[@"tasks"][3][@"title"] isEqual:@"旧名称"],@"deleted record never resurrects");Check([batch[@"series"][0][@"changes"] count]==1,@"future template has dated field patch");
 batch=DDLSeriesEdit(tasks,series,tasks[1],edited,2,NO);Check([batch[@"tasks"][0][@"title"] isEqual:@"新名称"] && [batch[@"tasks"][0][@"completed"] boolValue] && [batch[@"tasks"][0][@"due"] isEqual:tasks[0][@"due"]],@"entire series changes history metadata without deadlines or completion");batch=DDLSeriesEdit(tasks,series,tasks[1],edited,2,YES);Check([batch[@"tasks"][2][@"notes"] isEqual:@"新备注"],@"explicit override changes exception");
 Check([DDLRemaining([now dateByAddingTimeInterval:259140],now,NO) isEqual:@"剩余 2 天 23 小时"],@"nearly three days exposes hours");Check([DDLRemaining([now dateByAddingTimeInterval:86340],now,NO) isEqual:@"剩余 23 小时 59 分钟"],@"under day exposes minutes");Check([DDLRemaining([now dateByAddingTimeInterval:59],now,NO) isEqual:@"剩余不足 1 分钟"],@"under minute explicit");
 NSDictionary *backup=AMBackupEnvelope(tasks,&error);Check([backup[@"courses"] isEqual:catalog] && AMDecodeBackup(backup,&error),@"v4 backup includes catalog");Check(AMDecodeBackup(@{@"format":@"am-helper-backup-v3",@"tasks":tasks,@"submissions":@[],@"series":series,@"calendarOverrides":@{}},&error),@"legacy v3 remains accepted");printf("PASS: %lu task management assertions\n",checks);
}return 0;}
